'0,496 0,221 15,158 55,91 115,37 172,21 223,35 260,73 285,149 295,221 295,496',
'0,496 0,327 27,290 44,238 22,203 28,139 58,105 45,72 73,33 117,7 166,8 214,35 230,76 216,110 253,156 250,239 231,278 295,324 295,496',
'0,496 0,361 30,328 12,270 9,183 34,95 90,47 144,37 206,51 257,113 278,188 279,267 261,303 295,356 295,496',
