'0,496 0,193 22,112 61,65 122,42 182,36 235,61 270,102 284,156 295,230 295,496',
'0,496 0,295 35,260 30,220 5,151 19,88 49,50 115,17 175,4 223,26 267,77 283,143 265,203 242,248 274,290 295,307 295,496',
