function smoothPortraitMask(text){const a=text.split(' ').map(p=>p.split(',').map(Number));const mid=(p,q)=>[(p[0]+q[0])/2,(p[1]+q[1])/2];let d='M'+mid(a.at(-1),a[0]).join(' ');a.forEach((p,i)=>{d+=' Q'+p.join(' ')+' '+mid(p,a[(i+1)%a.length]).join(' ');});return d+' Z';}
character=function(index,mood='happy',barista=false){if(barista)return baristaArt(index,mood,true);const n=(index+(sim?.shift===3?2:0))%10,col=n%5,row=Math.floor(n/5),x=[9,318,623,928,1233][col],y=row?518:10;return `<svg class="supplied-avatar" viewBox="0 0 295 496" aria-hidden="true"><defs><clipPath id="portrait-${index}"><path d="${smoothPortraitMask(portraitMasks[n])}"/></clipPath></defs><image clip-path="url(#portrait-${index})" href="assets/customer-roster.png" x="${-x}" y="${-y}" width="1536" height="1024"/></svg>`;};
const TRAINING=[{id:'basic',name:'Quick orientation',fee:0,defects:50,quality:72,detail:'50% of helper drinks need a remake. You handle corrections.'},{id:'coached',name:'Coached practice',fee:15,defects:25,quality:84,detail:'25% of helper drinks need a remake. More consistent preparation.'},{id:'complete',name:'Full training',fee:30,defects:0,quality:98,detail:'98% drink quality, with no helper-caused remakes in this demo.'}];
const hirePower=POWERUPS.find(p=>p.id==='helper');Object.assign(hirePower,{cost:30,benefit:'Hire a barista for $30 per shift, then choose $0, $15 or $30 of training.',strength:'Adds drink capacity. Better training reduces defects and rework.',weakness:'Low-cost training creates remake work. Both workers still share the oven.'});
const StaffBase=CampaignCafe;
CampaignCafe=class extends StaffBase{
 constructor(...args){super(...args);this.helperTraining=args[3]?(journey.rentalTraining||'basic'):null;this.helperDrinks=0;this.helperDefects=0;this.staffingCost=args[3]?30:0;this.trainingCost=args[3]?TRAINING.find(t=>t.id===this.helperTraining).fee:0;if(args[3])this.costs+=20+this.trainingCost;}
 addOrder(){const o=super.addOrder();if(this.shift===3)o.name=['Maya','Lily','Sophie','Ava','Zoe','Noah','Leo','Amir','Ethan','Miles'][(o.id+1)%10];return o;}
 hire(level='basic'){const t=TRAINING.find(t=>t.id===level);if(!t||this.helper||!this.helperUnlocked||this.cash+this.profit<30+t.fee)return false;this.helper=true;this.helperTraining=level;this.staffingCost=30;this.trainingCost=t.fee;this.costs+=30+t.fee;return true;}
 complete(job,o){super.complete(job,o);if(job.worker!=='helper'||job.key!=='drink')return;const t=TRAINING.find(t=>t.id===this.helperTraining)||TRAINING[0];this.helperDrinks++;const flawed=t.id==='basic'?this.helperDrinks%2===1:t.id==='coached'?this.helperDrinks%4===1:false;const score=flawed?t.quality:98;for(const k of FIELDS)o.fills[k]=score;o.presentationScore=score;o.helperQuality=score;if(flawed)this.helperDefects++;}
 report(){return {...super.report(),staffingCost:this.staffingCost||0,trainingCost:this.trainingCost||0,helperDefects:this.helperDefects||0,helperTraining:this.helperTraining};}
};
function chooseTraining(reserve=false){closeStation();paused=true;modalKind='training';document.querySelector('.modal-backdrop')?.remove();const budget=reserve?journey.cash:sim.cash+sim.profit;const el=document.createElement('div');el.className='modal-backdrop';el.innerHTML=`<section class="modal training-modal" role="dialog" aria-modal="true" aria-label="Barista hiring and training"><h2>Hire & train your barista</h2><p><b>Hiring: $30 / shift</b> · Available: $${budget.toFixed(2)}</p><p>Training is a separate cost for this shift. Poor preparation creates remake tickets and uses more ingredients.</p><div class="training-options">${TRAINING.map(t=>`<article><h3>${t.name}</h3><b>Training $${t.fee} · Total $${30+t.fee}</b><p>${t.detail}</p><button class="big-btn" data-training="${t.id}" ${budget<30+t.fee?'disabled':''}>${reserve?'Reserve':'Hire'} · $${30+t.fee}</button></article>`).join('')}</div><small>Remake rates describe the helper’s preparation in this game. Oven timing and handoffs are still your responsibility.</small><button class="big-btn gold" id="training-cancel">Not now</button></section>`;document.body.appendChild(el);el.querySelectorAll('[data-training]').forEach(b=>b.onclick=()=>{const t=TRAINING.find(t=>t.id===b.dataset.training);if(reserve){if(journey.cash<30+t.fee||journey.rental)return;journey.rental=true;journey.rentalTraining=t.id;journey.rentalCost=30+t.fee;journey.cash-=journey.rentalCost;closeModal();showShop();}else if(sim.hire(t.id)){closeModal();update();toast(`${t.name}: barista hired for $${30+t.fee}.`);}});el.querySelector('#training-cancel').onclick=()=>{closeModal();if(reserve)showShop();};el.querySelector('button:not(:disabled)').focus();}
const staffShop=showShop;
showShop=function(){staffShop();if(shopSelected==='helper'&&!journey.rental){document.querySelector('#buy-power').textContent=journey.cash>=30?'Choose training · from $30':'Need $'+(30-journey.cash).toFixed(2)+' more';document.querySelector('#buy-power').onclick=()=>chooseTraining(true);}};
const staffModal=showModal;
showModal=function(kind){if(!sim?.tutorial&&kind==='helper'){if(!sim.helper)chooseTraining();return;}staffModal(kind);if(!sim?.tutorial&&kind==='rush'){const b=document.querySelector('#accept-helper');if(b){b.textContent=sim.helper?'Already hired':'Hire & train · from $30';b.onclick=()=>chooseTraining();const p=b.parentElement.querySelectorAll('p')[1];if(p)p.innerHTML=`<b>Hiring $30 + training $0–$30.</b> Better training means fewer defects. Available: $${(sim.cash+sim.profit).toFixed(2)}.`;}}};
const staffReport=showReport;
showReport=function(){staffReport();const r=journey.reports.at(-1);document.querySelector('.service-review')?.insertAdjacentHTML('beforeend',`<h3>Staffing & training costs</h3><p>Hiring: <b>$${r.staffingCost||0}</b> · Training: <b>$${r.trainingCost||0}</b> · Helper drinks needing correction: <b>${r.helperDefects||0}</b>.</p>`);};
// Holding one button dispenses a repeatable smooth swirl. Releasing stops immediately.
let automaticDose=null;
function autoToppingPoints(type,fraction){const count=Math.max(2,Math.floor(150*fraction));return Array.from({length:count},(_,i)=>{const t=i/149;if(type==='Whipped Cream'){const radius=78*(1-t)+4;return {x:230-radius*Math.cos(t*Math.PI*8),y:151-99*t+9*(1-t)*Math.sin(t*Math.PI*8)};}if(type==='Cold Foam')return {x:230+80*Math.sin(t*Math.PI*7),y:146-31*t+5*Math.cos(t*Math.PI*7)};return {x:230+73*(1-t*.7)*Math.sin(t*Math.PI*8-Math.PI/2),y:151-79*t};});}
function stopAutomaticDose(){const a=automaticDose;if(!a)return;automaticDose=null;cancelAnimationFrame(a.raf);const o=sim?.orders.find(o=>o.id===a.id);if(o&&a.fraction>.04){o.toppingStrokes=o.toppingStrokes.filter(s=>s.type!==a.type);sim.addToppingStroke(a.type,autoToppingPoints(a.type,a.fraction),o);}cancelToppingGesture();if(stationPanel?.key==='topping'){updateToppings();update();updateDispenser();}}
function updateDispenser(){const button=document.querySelector('#auto-dispense');if(!button)return;const o=sim.orders.find(o=>o.id===stationPanel.id),stroke=o?.toppingStrokes.find(s=>s.type===toppingTool),pct=automaticDose?Math.round(automaticDose.fraction*100):stroke?Math.min(100,Math.round(stroke.points.length/150*100)):0;button.disabled=!toppingTool;button.textContent=toppingTool==='Cinnamon'?'Add cinnamon stick':toppingTool?`${pct>=100?'✓ Complete':'Hold to dispense'} · ${pct}%`:'Choose a topping first';document.querySelector('#dose-meter').value=pct;}
function beginAutomaticDose(){if(automaticDose||!toppingTool||paused)return;const o=sim.orders.find(o=>o.id===stationPanel.id);if(toppingTool==='Cinnamon'){sim.addToppingStroke('Cinnamon',[{x:265,y:113}],o);updateToppings();updateDispenser();return;}const existing=o.toppingStrokes.find(s=>s.type===toppingTool);let fraction=(existing?.points.length||0)/150;if(fraction>=1)return;const a={id:o.id,type:toppingTool,fraction,last:performance.now(),raf:0};automaticDose=a;toppingGesture={type:a.type,points:[]};const step=now=>{if(automaticDose!==a)return;if(!document.querySelector('#auto-dispense')||!stationPanel||sim.finished){stopAutomaticDose();return;}const dt=Math.min(.08,(now-a.last)/1000);a.last=now;if(!paused)a.fraction=Math.min(1,a.fraction+dt/(a.type.includes('Drizzle')?2.5:3.5));toppingGesture={type:a.type,points:autoToppingPoints(a.type,a.fraction)};drawToppings();updateDispenser();if(a.fraction>=1)stopAutomaticDose();else a.raf=requestAnimationFrame(step);};a.raf=requestAnimationFrame(step);}
const autoOpen=openToppings;
openToppings=function(){autoOpen();if(stationPanel?.key!=='topping')return;document.querySelector('#topping-help').textContent='Choose a topping. Hold Dispense: the can moves and decorates for you. Release to stop.';document.querySelector('.topping-legend').innerHTML='<b>Automatic swirls</b><span>Hold the button to dispense.</span><span>Release to stop.</span><span>Reach 100% for even coverage.</span><strong id="presentation-score"></strong>';const canvas=document.querySelector('#decoration-canvas');canvas.onpointerdown=null;canvas.onkeydown=null;canvas.onkeyup=null;document.querySelectorAll('[data-top-tool]').forEach(b=>{b.onpointerdown=null;b.onkeydown=null;b.onclick=()=>{stopAutomaticDose();toppingTool=b.dataset.topTool;updateToppings();updateDispenser();};});document.querySelector('.applied-toppings').insertAdjacentHTML('beforebegin','<div class="dose-controls"><button id="auto-dispense" class="big-btn" disabled>Choose a topping first</button><progress id="dose-meter" max="100" value="0"></progress></div>');const b=document.querySelector('#auto-dispense');b.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();b.setPointerCapture(e.pointerId);beginAutomaticDose();};b.onpointerup=stopAutomaticDose;b.onpointercancel=stopAutomaticDose;b.onlostpointercapture=stopAutomaticDose;b.onkeydown=e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();if(!e.repeat)beginAutomaticDose();}};b.onkeyup=e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();stopAutomaticDose();}};b.onblur=stopAutomaticDose;canvas.insertAdjacentHTML('beforeend','<g id="auto-nozzle"></g>');updateDispenser();};
const autoDraw=drawToppings;
drawToppings=function(){const o=sim?.orders.find(o=>o.id===stationPanel?.id);let saved;if(o&&automaticDose){saved=o.toppingStrokes;o.toppingStrokes=saved.filter(s=>s.type!==automaticDose.type);}autoDraw();if(saved)o.toppingStrokes=saved;const nozzle=document.querySelector('#auto-nozzle');if(nozzle){const p=toppingGesture?.points.at(-1);nozzle.innerHTML=automaticDose&&p?`<g transform="translate(${p.x-22} ${p.y-80})"><rect width="44" height="56" rx="9" fill="${automaticDose.type.includes('Caramel')?'#d78a2c':automaticDose.type.includes('Chocolate')?'#68351f':'#edf7fa'}" stroke="#65432e" stroke-width="2"/><rect y="13" width="44" height="25" fill="#75a3c6"/><text x="22" y="29" font-size="9" text-anchor="middle" fill="white">${automaticDose.type.includes('Drizzle')?'SAUCE':'CREAM'}</text><path d="M9 57h26l-9 13h-8Z" fill="#aaa"/><path d="M22 70v10" stroke="#fff4df" stroke-width="7" stroke-linecap="round"/></g>`:'';}updateDispenser();};
const autoClose=closeStation;
closeStation=function(){stopAutomaticDose();autoClose();};
window.addEventListener('blur',stopAutomaticDose);
const automaticToppingHelp=updateToppings;
updateToppings=function(){automaticToppingHelp();const help=document.querySelector('#topping-help');if(help)help.textContent=toppingTool==='Cinnamon'?'Press Add cinnamon stick to place it on the drink.':'Hold the green Dispense button. The topping flows automatically; release to stop.';updateDispenser();};
